$(document).ready(function(){var e=$(".popup-video");$(".is-popup").on("click",function(o){o.preventDefault();var i=$(this).attr("href")+"&enablejsapi=1";e.html(`\n            <div class="overly-close"></div>\n            <div class="popup-body">\n                <iframe width="560" height="315" src="${i}" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen>\n                </iframe>\n            </div>\n        `),e.addClass("show"),e.find("iframe").on("load",function(){this.contentWindow.postMessage('{"event":"command","func":"playVideo","args":""}',"*")})}),$(".popup-video").on("click",".overly-close",function(){e.removeClass("show"),$(".popup-video").html("")})});